/**
 * Configuration for a specific placement of an external tool. If null, no configuration is present.
 */
export interface ContextExternalToolPlacement {
  /**
   * Whether this placement is enabled
   */
  enabled?: boolean;
  /**
   * The launch URL for this specific placement. Overrides the tool's default URL. For LTI 1.1 tools only.
   */
  url?: string;
  /**
   * The launch URL for this specific placement. Overrides the tool's default target_link_uri. For LTI 1.3 tools only.
   */
  target_link_uri?: string;
  /**
   * The text/label to display for this placement. Overridable by 'labels' in placement configuration.
   */
  text?: string;
  /**
   * The localized label for this placement. This is the resolved text after applying internationalization.
   */
  label?: string;
  /**
   * Internationalization labels for this placement. Keys are locale codes, values are localized text.
   */
  labels?: Record<string, unknown>;
  /**
   * The LTI message type for this placement. Not all placements support all message types.
   */
  message_type?: string;
  /**
   * The width of the iframe or popup for this placement
   */
  selection_width?: number;
  /**
   * The height of the iframe or popup for this placement
   */
  selection_height?: number;
  /**
   * The width of the launch window. Not standard everywhere yet.
   */
  launch_width?: number;
  /**
   * The height of the launch window. Not standard everywhere yet.
   */
  launch_height?: number;
  /**
   * The URL of the icon for this placement
   */
  icon_url?: string;
  /**
   * The Canvas icon class to use for this placement instead of an icon URL
   */
  canvas_icon_class?: string;
  /**
   * Whether to allow fullscreen mode for this placement (top_navigation placement only)
   */
  allow_fullscreen?: boolean;
  /**
   * Custom fields to be sent with this placement's launch. Merged with tool-level custom fields.
   */
  custom_fields?: Record<string, unknown>;
  /**
   * Controls who can see this placement
   */
  visibility?: string;
  /**
   * Comma-separated list of Canvas permissions required to launch from this placement. The user must have all permissions in order to launch the tool.
   */
  required_permissions?: string;
  /**
   * Default display state for navigation placements. Only applies to account_navigation and course_navigation placements.
   */
  default?: string;
  /**
   * The layout type to use when launching the tool. For global_navigation and analytics_hub, defaults to 'full_width'.
   */
  display_type?: string;
  /**
   * When set to '_blank', opens placement in a new tab. Only '_blank' is supported.
   */
  windowTarget?: string;
  /**
   * Comma-separated list of media types that the tool can accept. Only valid for file_menu placement.
   */
  accept_media_types?: string;
  /**
   * If true, the tool will be launched in the tray. Only used by the editor_button placement.
   */
  use_tray?: boolean;
  /**
   * An SVG path to use instead of an icon_url. Only valid for global_navigation placement.
   */
  icon_svg_path_64?: string;
  /**
   * Whether this placement should only be available at the root account level. Only applies to account_navigation placement.
   */
  root_account_only?: boolean;
  /**
   * A description of this placement. Only valid for submission_type_selection placement. Maximum length of 255 characters.
   */
  description?: string;
  /**
   * Whether resource selection is required for this placement. Only valid for submission_type_selection placement.
   */
  require_resource_selection?: boolean;
  /**
   * If true, the tool will send the SIS email in the lis_person_contact_email_primary launch property. LTI 1.1 only.
   */
  prefer_sis_email?: boolean;
  /**
   * If true, query parameters from the launch URL will not be copied to the POST body. LTI 1.1 only.
   */
  oauth_compliant?: boolean;
}

